	private void assertAggregateWitnessQuote(boolean nullable) throws Exception {
		String query = query(false).replace("SELECT ?row ?s", "SELECT (COUNT(*) AS ?count)");
		if (!nullable) {
			query = query.replace("OPTIONAL { ?row :candidate ?s }", "?row :candidate ?s .");
		}
		long expected = nullable ? 2L : 1L;
		assertThat(count(memoryRepository, query, false, null)).as("independent MemoryStore count")
				.isEqualTo(expected);
		assertThat(count(nativeRepository, query, false, null)).as("generic LMDB count").isEqualTo(expected);
		List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
		long opensBefore = LmdbNativeKernelExecution.AGG_OPENED.get();
		try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.captureSelections(selected)) {
			assertThat(count(nativeRepository, query, true, LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED))
					.as("the interpreted aggregate must preserve nullable EXISTS semantics")
					.isEqualTo(expected);
		}
		assertThat(LmdbNativeKernelExecution.AGG_OPENED.get()).isGreaterThan(opensBefore);
		assertThat(selected.stream()
				.filter(selection -> selection.id().equals(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED)))
						.as("the aggregate strategy must actually open before its quote is inspected")
						.singleElement()
						.satisfies(selection -> {
							assertThat(selection.quote()).isNotNull();
							assertThat(selection.quote().expectedFeatures()).isNotNull();
							double membership = selection.quote()
									.expectedFeatures()[LmdbNativeCostVector.Feature.MEMBERSHIP_TEST
											.ordinal()];
							if (nullable) {
								assertThat(membership)
										.as("the final quote must include the native nullable EXISTS probe")
										.isPositive();
							} else {
								assertThat(membership).as("the assured direct witness has no native membership hook")
										.isZero();
							}
						});
	}

	private long count(SailRepository repository, String query, boolean nativeEnabled, String forced) {
		set(NATIVE, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(forced);
			try (TupleQueryResult result = prepared.evaluate()) {
				assertThat(result.hasNext()).isTrue();
				long count = Long.parseLong(result.next().getValue("count").stringValue());
				assertThat(result.hasNext()).isFalse();
				return count;
			}
		}
	}

	private void assertAnswerParity(String query) throws Exception {
		assertAnswerParity(query, EXPECTED, false);
	}

	private void assertAnswerParity(String query, List<String> expected, boolean requireIr) throws Exception {
		assertAnswerParity(query, expected, requireIr, false);
	}

	private void assertAnswerParity(String query, List<String> expected, boolean requireIr, boolean compiled)
			throws Exception {
		if (compiled) {
			set(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "true");
			set(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "true");
			set(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, "0");
		}
		String route = compiled ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL
				: LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED;
		assertThat(rows(memoryRepository, query, false, null)).as("independent MemoryStore answer bag")
				.containsExactlyElementsOf(expected);
		assertThat(rows(nativeRepository, query, false, null)).as("generic LMDB answer bag")
				.containsExactlyElementsOf(expected);
		List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
		long bindsBefore = (compiled ? LmdbNativeKernelExecution.COMPILED_BINDS
				: LmdbNativeKernelExecution.INTERPRETED_BINDS).get();
		List<String> actual;
		try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.captureSelections(selected)) {
			actual = rows(nativeRepository, query, true, requireIr ? route : route + ",nestedLoop");
		}
		assertThat(selected).as("a requested route must actually open, not merely be quoted")
				.isNotEmpty()
				.allMatch(selection -> selection.id().equals(route)
						|| !requireIr && selection.id().equals("nestedLoop"));
		boolean kernelOpened = selected.stream().anyMatch(selection -> selection.id().equals(route));
		if (requireIr) {
			assertThat(kernelOpened).as("the eligible control must retain the requested kernel strategy").isTrue();
		}
		if (kernelOpened) {
			assertThat((compiled ? LmdbNativeKernelExecution.COMPILED_BINDS
					: LmdbNativeKernelExecution.INTERPRETED_BINDS).get()).isGreaterThan(bindsBefore);
		}
		assertThat(actual).as("a bound nonmatching subject must not borrow another subject's witness")
				.containsExactlyElementsOf(expected);
	}

	private static String query(boolean composite) {
		String body = composite ? "{ ?s :witness :yes } UNION { ?s :otherWitness :yes }" : "?s :witness :yes";
		return query(body);
	}

	private static String query(String body) {
		return "PREFIX : <" + EX + "> SELECT ?row ?s WHERE { "
				+ "?row :anchor :yes . OPTIONAL { ?row :candidate ?s } FILTER EXISTS { " + body + " } }";
	}

	private List<String> rows(SailRepository repository, String query, boolean nativeEnabled, String forced) {
		set(NATIVE, Boolean.toString(nativeEnabled));
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(forced);
			try (TupleQueryResult result = prepared.evaluate()) {
				while (result.hasNext()) {
					BindingSet row = result.next();
					rows.add(row.getValue("row").stringValue() + "|"
							+ (row.hasBinding("s") ? row.getValue("s").stringValue() : "<unbound>"));
				}
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}
